import { test, expect } from '@playwright/test';

test('manual annotation survives reload, copied boxes remain drafts, and controls work',async({page})=>{
  const errors=[];page.on('pageerror',error=>errors.push(error.message));
  await page.goto('/');
  await expect(page.locator('#progress')).toHaveText('0 / 2 frame reviewed');
  await expect(page.locator('#position')).toContainText('1 / 2');
  await page.getByRole('button',{name:'Tandai reviewed dan simpan'}).click();
  await expect(page.locator('#message')).toContainText('Isi reviewer');
  await page.getByLabel('Nama reviewer').fill('Browser test');
  await page.getByLabel('Normal',{exact:true}).check();
  const canvas=page.locator('canvas');
  const box=await canvas.boundingBox();
  await page.mouse.move(box.x+box.width*.28,box.y+box.height*.21);
  await page.mouse.down();
  await page.mouse.move(box.x+box.width*.55,box.y+box.height*.88,{steps:5});
  await page.mouse.up();
  await expect(page.getByLabel('ID orang 1')).toHaveValue('person-1');
  await page.getByLabel('ID orang 1').fill('worker-a');
  await page.getByRole('button',{name:'Tandai reviewed dan simpan'}).click();
  await expect(page.locator('#progress')).toHaveText('1 / 2 frame reviewed');
  await page.getByRole('button',{name:'Berikutnya',exact:true}).click();
  await page.getByRole('button',{name:'Salin box frame sebelumnya sebagai draft'}).click();
  await expect(page.getByLabel('ID orang 1')).toHaveValue('worker-a');
  await page.getByRole('button',{name:'Simpan draft',exact:true}).click();
  await expect(page.locator('#progress')).toHaveText('1 / 2 frame reviewed');
  await page.reload();
  await expect(page.locator('#progress')).toHaveText('1 / 2 frame reviewed');
  await expect(page.getByLabel('ID orang 1')).toHaveValue('worker-a');
  await page.getByRole('button',{name:'Cari belum direview'}).click();
  await expect(page.locator('#position')).toContainText('2 / 2');
  await page.getByRole('button',{name:'1',exact:true}).click();
  await page.getByRole('button',{name:'Hapus box terpilih'}).click();
  await expect(page.getByLabel('ID orang 1')).toHaveCount(0);
  await page.getByLabel('Kosong',{exact:true}).check();
  await page.getByRole('button',{name:'Tandai reviewed dan simpan'}).click();
  await expect(page.locator('#progress')).toHaveText('2 / 2 frame reviewed');
  await expect(page.getByRole('button',{name:'Berikutnya',exact:true})).toBeDisabled();
  expect(errors).toEqual([]);
});
